-- New York State (Subpart 7-2): 78 requirements.
--
-- Extracted section by section from the regulation. 70 were read directly off the rule text;
-- 8 are flagged needs_verification and must be confirmed before a paying camp sees
-- them. Labels and summaries are our own plain English — the product links to the source and
-- never quotes the rule as fact.
--
-- 6 aquatics rows use `any_of` because they apply to a pool OR a beach. Tagged has_pool
-- alone they would not have fired for a lakefront-only camp, silently giving that camp a clean
-- bill for rules it is subject to.
--
-- Ratio requirements carry evidence_type 'roster' because proving them needs camper counts.
-- That feature does not exist yet, so the engine falls back to "attach a document" while
-- keeping the real type — they begin evaluating automatically the day the roster ships.

with p as (select id from compliance_profiles where code = 'NY-STATE')
insert into compliance_requirements
  (profile_id, req_code, label, summary, category, evidence_type, evidence_rule,
   evidence_hint, frequency, applies_when, citation, citation_url, verify_status, sort_order)
values
  ((select id from p), 'NY-0401', 'Hold a current camp permit and post it where it can be seen', 'The camp may not operate without a permit from the permit-issuing official, and that permit must be displayed in a conspicuous place on the property. Permits run one year, are not transferable, and end when the operator changes.', 'permit', 'document', '{}'::jsonb, 'The current signed permit certificate plus a photo or note showing where it is posted on site.', 'annual', '{}'::jsonb, '10 NYCRR 7-2.4(a), (f), (h)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.4', 'verified', 0),
  ((select id from p), 'NY-0402', 'File the permit application at least 60 days before opening day', 'The operator submits the application for a permit to operate to the permit-issuing official no later than 60 days before the first day of camp operation each year.', 'permit', 'document', '{}'::jsonb, 'A dated copy of the submitted permit application showing it went in at least 60 days before opening.', 'annual', '{}'::jsonb, '10 NYCRR 7-2.4(c)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.4', 'verified', 10),
  ((select id from p), 'NY-0403', 'Review the safety plan every year and file the update or a written affirmation', 'The operator reviews the written camp safety plan annually and updates it to keep pace with current standards. Updated plans go to the permit-issuing official; in a year with no changes the operator sends a written statement that the approved plan is still up to date and complete.', 'permit', 'plan_section', '{}'::jsonb, 'The dated annual plan review record plus either the submitted revised plan or the written affirmation letter.', 'annual', '{}'::jsonb, '10 NYCRR 7-2.4(c)(1)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.4', 'verified', 20),
  ((select id from p), 'NY-0404', 'File a new application when the camp name, owner or operator changes', 'A change in the camp''s name, ownership or operator triggers a fresh permit application. An existing permit does not carry over to a new operator and expires on that change.', 'permit', 'document', '{}'::jsonb, 'The application filed at the time of the ownership, name or operator change.', 'on_event', '{}'::jsonb, '10 NYCRR 7-2.4(c)(2), (h)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.4', 'verified', 30),
  ((select id from p), 'NY-0501', 'Appoint a camp director who meets the age, education and experience minimums', 'Every camp needs a named director responsible for supervising the program. The director must hold a bachelor''s degree or meet the minimum age for the camp type, plus at least 24 weeks of prior administrative or supervisory camping experience or an equivalent the State accepts.', 'personnel', 'document', '{}'::jsonb, 'The director''s personnel file showing degree or date of birth and documented prior supervisory camp weeks.', 'seasonal', '{}'::jsonb, '10 NYCRR 7-2.5(a)(1)-(2)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.5', 'verified', 40),
  ((select id from p), 'NY-0502', 'Clear the camp director through the abuse register and the conviction statement', 'Before serving, the director needs a notification from the State Central Register of Abuse and Maltreatment showing no investigation report, and must file the State''s certified statement on criminal convictions and pending criminal actions for the permit-issuing official to evaluate.', 'personnel', 'screening', '{}'::jsonb, 'The State Central Register clearance and the signed Prospective Children''s Camp Director Certified Statement on file.', 'on_event', '{}'::jsonb, '10 NYCRR 7-2.5(a)(3)-(4)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.5', 'needs_verification', 50),
  ((select id from p), 'NY-0503', 'Verify each counselor''s age, experience or training, and character references', 'Counselors must be at least 18 at an overnight camp and 16 at a day camp, and must either have camping and child supervision experience or have completed a training course the permit-issuing official accepts. The operator must check each candidate''s background and character through reasonable and diligent inquiries including submitted references.', 'personnel', 'screening', '{}'::jsonb, 'A per-counselor hiring file with proof of age, the training certificate or experience record, and notes from contacting references.', 'seasonal', '{}'::jsonb, '10 NYCRR 7-2.5(b)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.5', 'verified', 60),
  ((select id from p), 'NY-0504', 'Check every employee and volunteer against the Sex Offender Registry each year', 'The camp checks each employee and volunteer against the DCJS Sex Offender Registry before their first day at camp and again every year before they arrive, and keeps the list of names submitted and the search results on file at the camp site.', 'personnel', 'screening', '{}'::jsonb, 'The written log of names submitted to DCJS with the dated search result returned for each person.', 'annual', '{}'::jsonb, '10 NYCRR 7-2.5(l)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.5', 'verified', 70),
  ((select id from p), 'NY-0505', 'Staff overnight camp activities at 1:10, or 1:8 for campers under eight', 'At an overnight camp the counselor to camper ratio is one to ten for campers eight and over and one to eight for younger campers, unless a specialty activity sets a tighter number. No more than twenty percent of the required counselors may be seventeen years old.', 'supervision', 'roster', '{}'::jsonb, 'Daily activity assignment sheets showing counselor counts against camper counts, plus a staff age list proving the seventeen-year-old share.', 'ongoing', '{"camp_type": "overnight"}'::jsonb, '10 NYCRR 7-2.5(c)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.5', 'verified', 80),
  ((select id from p), 'NY-0506', 'Staff day camp activities at 1:12', 'A summer day or traveling summer day camp keeps a general ratio of one counselor for every twelve campers, and must still meet the tighter specialty activity ratios during those activities. The permit-issuing official may require stricter ratios.', 'supervision', 'roster', '{}'::jsonb, 'Daily group assignment sheets showing counselor to camper counts for each group.', 'ongoing', '{"camp_type": "day"}'::jsonb, '10 NYCRR 7-2.5(d)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.5', 'verified', 90),
  ((select id from p), 'NY-0507', 'List passive activities in the plan and hold them to 1:25', 'During low-risk activities in a defined area where campers are spectators or have limited mobility and use no equipment, the ratio may relax to one counselor per twenty-five campers. Those activities must be named in the approved safety plan and normal ratios resume as soon as the activity ends.', 'supervision', 'plan_section', '{}'::jsonb, 'The safety plan section listing which activities count as passive, plus schedules showing staffing during them.', 'ongoing', '{}'::jsonb, '10 NYCRR 7-2.5(b)(1)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.5', 'verified', 100),
  ((select id from p), 'NY-0508', 'Get night supervision approved in the plan and keep a counselor on each sleeping level', 'Supervision may be reduced while campers rest or sleep only in the arrangement described in the approved safety plan, and only where campers stay protected from unreasonable risk. In a multi-story sleeping building at least one counselor must be present on every level in use.', 'supervision', 'plan_section', '{}'::jsonb, 'The approved plan text describing the night supervision arrangement, plus the nightly cabin or floor duty roster.', 'ongoing', '{"camp_type": "overnight"}'::jsonb, '10 NYCRR 7-2.5(c)(1), 7-2.16(f)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.5', 'verified', 110),
  ((select id from p), 'NY-0509', 'Keep campers in sight or earshot and be able to account for every one of them', 'Supervision must be adequate to protect campers from unreasonable risk to health or safety, including physical or sexual abuse and public health hazards. At minimum staff must be able to see or hear each camper during activities and know where each camper is at any moment.', 'supervision', 'attestation', '{}'::jsonb, 'The head count and camper accounting records used at transitions, plus the plan procedure staff sign off on.', 'ongoing', '{}'::jsonb, '10 NYCRR 7-2.5(o)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.5', 'verified', 120),
  ((select id from p), 'NY-0510', 'Qualify the aquatics director and the swim instructor who assesses every camper', 'A camp aquatics director at least 21 with the required prior aquatics experience must oversee all swimming, hold lifeguard supervision and management training plus current CPR, and document an annual review of the swim safety plan. A certified progressive swimming instructor must assess each camper''s swimming ability before that camper takes part in aquatic activities.', 'personnel', 'certification', '{"min_count": 1}'::jsonb, 'The aquatics director''s training and CPR certificates, the signed annual swim plan review, the instructor''s certificate, and a swim classification list covering every camper.', 'annual', '{"any_of": {"has_pool": "true", "has_waterfront": "true"}}'::jsonb, '10 NYCRR 7-2.5(e), (f)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.5', 'verified', 130),
  ((select id from p), 'NY-0511', 'Keep every lifeguard certified at the supervision level the facility requires', 'Lifeguards must hold the lifeguarding, first aid and CPR certifications Part 6 requires for the type of bathing facility, be at least 17 (16 for up to half the guards on duty, 18 for wilderness swimming), and stay free of duties that distract them from watching the water.', 'personnel', 'certification', '{"min_count": 1}'::jsonb, 'A non-expired lifeguard certificate at the correct supervision level, plus first aid and CPR cards, for every guard on duty.', 'seasonal', '{"any_of": {"has_pool": "true", "has_waterfront": "true"}}'::jsonb, '10 NYCRR 7-2.5(g)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.5', 'verified', 140),
  ((select id from p), 'NY-0512', 'Qualify trip and activity leaders, with first aid and CPR where help is far off', 'A trip leader must be at least 18 with at least three comparable camp trips behind them or an accepted equivalent. Activity leaders must be competent in their activity and at least 18 for wilderness, climbing, riding, cycling, boating or swimming. Where the camp''s certified staff are not readily available, the leader or an accompanying staff member carries current first aid and CPR certificates.', 'personnel', 'certification', '{"min_count": 1}'::jsonb, 'Leader files showing prior trip history or activity competence, with current first aid and CPR cards for remote activities and trips.', 'seasonal', '{}'::jsonb, '10 NYCRR 7-2.5(h), (i)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.5', 'verified', 150),
  ((select id from p), 'NY-0513', 'Have a certified riflery instructor run the range', 'Riflery instruction requires a current instructor certificate from the National Rifle Association or an equivalent program generally accepted as providing a similar level of riflery skill.', 'personnel', 'certification', '{"min_count": 1}'::jsonb, 'The instructor''s current NRA or equivalent riflery instructor certificate.', 'seasonal', '{"has_riflery": true}'::jsonb, '10 NYCRR 7-2.5(j)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.5', 'verified', 160),
  ((select id from p), 'NY-0514', 'Cap counselors-in-training at ten percent and train them for their duties', 'Counselors-in-training are campers assigned to help an on-duty staff member and may never supervise campers on their own. They may fill no more than ten percent of the required counselor positions, must meet the age and prior-camper-season minimums for the camp type, and must get training specific to their duties plus camper orientation.', 'personnel', 'roster', '{}'::jsonb, 'A CIT roster with ages and prior camper seasons, the required-counselor math showing the ten percent cap, and CIT training sign-in sheets.', 'seasonal', '{}'::jsonb, '10 NYCRR 7-2.5(k)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.5', 'verified', 170),
  ((select id from p), 'NY-0515', 'Keep the approved safety plan and all staff qualification records on site', 'The operator develops the plan, gets it approved, keeps it at the camp and actually runs the camp by it. It must have a table of contents and cover personnel structure and job descriptions, facility operation and maintenance including the lightning risk assessment, and general and activity-specific supervision. Staff qualification records must also be held at camp for the inspector.', 'records', 'manual', '{}'::jsonb, 'The current approved safety plan on site with its personnel, facility and per-activity safety sections, alongside the staff qualification binder.', 'ongoing', '{}'::jsonb, '10 NYCRR 7-2.5(n), (n)(1), (n)(2), (n)(5), (l)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.5', 'verified', 180),
  ((select id from p), 'NY-0516', 'Cover fire safety in the plan, send it to the fire department, report fires in 24 hours', 'The plan''s fire section must cover evacuation and accounting for people, fire prevention, coordination with local fire officials, alarm testing and maintenance, extinguisher type and location, exit inspection, drills and the drill log, and electrical safety. A copy goes to the local fire district. Fires that damage a building, bring out the fire department, or threaten life or health are reported to the permit-issuing official within 24 hours.', 'fire', 'plan_section', '{}'::jsonb, 'The fire section of the approved plan, proof it was sent to the local fire district, and any 24-hour fire notifications sent.', 'annual', '{}'::jsonb, '10 NYCRR 7-2.5(n)(3)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.5', 'verified', 190),
  ((select id from p), 'NY-0517', 'Cover medical operations in the safety plan', 'The plan''s medical section must describe review of camper medical histories, initial health screening, daily health surveillance, first aid and emergency handling including outbreaks and child abuse allegations, medical and emergency services arrangements, the health director''s identity and duties, the health center, medicine storage and administration, the medical log, bloodborne pathogen precautions, 24-hour reporting and sanitation supervision.', 'medical', 'plan_section', '{}'::jsonb, 'The medical requirements section of the approved safety plan with each listed topic addressed.', 'annual', '{}'::jsonb, '10 NYCRR 7-2.5(n)(4)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.5', 'verified', 200),
  ((select id from p), 'NY-0518', 'Train staff and orient campers to the plan curricula and record who attended', 'The plan must contain a staff training outline (camp tour and hazards, chain of command, supervision and discipline, child abuse recognition and reporting, first aid, injury reporting, buddy system, lost swimmer and lost camper plans, lightning plan, fire drills, evacuation, activity-specific and trip training) and a camper orientation outline, each with a process to document attendance.', 'training', 'training', '{}'::jsonb, 'Signed staff training attendance sheets and camper orientation attendance records for each session, matched to the plan outlines.', 'per_session', '{}'::jsonb, '10 NYCRR 7-2.5(n)(6)-(7)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.5', 'verified', 210),
  ((select id from p), 'NY-0519', 'Send families a camper rights and responsibilities statement with enrollment forms', 'Any enrollment application or contract sent to a family must be accompanied by a written statement or brochure covering camper and operator rights and responsibilities, stating the camp must be permitted by the State Health Department and inspected twice yearly, and giving the address where inspection reports are filed.', 'records', 'document', '{}'::jsonb, 'The current enrollment packet showing the rights and responsibilities insert with the inspection report filing address.', 'annual', '{}'::jsonb, '10 NYCRR 7-2.5(p)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.5', 'verified', 220),
  ((select id from p), 'NY-0601', 'Disinfect the on-site water supply and hold at least 0.2 mg/L free chlorine', 'A groundwater source must be disinfected, normally by chlorination, with a free chlorine residual of at least 0.2 milligrams per litre held in the distribution system. Surface sources need approved filtration and disinfection. No waiver from disinfection is available.', 'water', 'document', '{}'::jsonb, 'Daily free chlorine residual readings from the distribution system showing at least 0.2 mg/L.', 'daily', '{"water_source": "well"}'::jsonb, '10 NYCRR 7-2.6(c)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.6', 'verified', 230),
  ((select id from p), 'NY-0602', 'Run the annual water system start-up 15 days before the camp is occupied', 'For a water system not in continuous use, the operator disinfects the mains to the prescribed chlorine concentrations, then flushes and measures residuals on the two following days, then collects a total coliform sample, all completed 15 days before the property is occupied.', 'water', 'document', '{}'::jsonb, 'The dated start-up record showing main disinfection concentrations, two days of post-flush residual readings, and the follow-up coliform sample.', 'annual', '{"water_source": "well"}'::jsonb, '10 NYCRR 7-2.6(d)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.6', 'verified', 240),
  ((select id from p), 'NY-0603', 'Sample each water source for total coliform before opening and during the season', 'At least one total coliform sample must come from each source before the season opens and at least one more during the season, taken at a representative point in the distribution system and analysed by a New York State certified laboratory. A camp operating more than 30 days in a calendar year samples for each month it operates.', 'water', 'water_sample', '{}'::jsonb, 'Certified laboratory coliform reports for each source covering the pre-season sample and every required in-season or monthly sample.', 'monthly', '{}'::jsonb, '10 NYCRR 7-2.6(f)(1)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.6', 'needs_verification', 250),
  ((select id from p), 'NY-0604', 'Run a nitrate analysis on each water system every year', 'Nitrate must be analysed annually for every system, and both nitrate and nitrite for any new source, against maximum contaminant levels of 10 mg/L nitrate and 1 mg/L nitrite as nitrogen.', 'water', 'water_sample', '{}'::jsonb, 'The current year''s certified laboratory nitrate result for each system, plus nitrate and nitrite results for any new source.', 'annual', '{"water_source": "well"}'::jsonb, '10 NYCRR 7-2.6(f)(2), (e)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.6', 'verified', 260),
  ((select id from p), 'NY-0605', 'Report bad samples and water supply incidents within 24 hours', 'A sample positive for total coliform or E. coli must be reported to the permit-issuing official within 24 hours of the lab notifying the camp. Any incident or condition affecting the quantity or quality of the on-site supply is reported on the same clock, and no source or treatment change may be made without prior approval.', 'water', 'document', '{}'::jsonb, 'Dated notifications to the permit-issuing official filed with the lab report or incident record, plus written approvals for any source or treatment change.', 'on_event', '{}'::jsonb, '10 NYCRR 7-2.6(f)(4), (m)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.6', 'verified', 270),
  ((select id from p), 'NY-0606', 'Keep daily treatment reports and file water analysis results monthly', 'Water treatment operation reports must be kept accurately every day on department-approved forms and submitted within 10 days after the end of each month of operation. Pre-operational analysis reports go in before the permit issues, and other required analysis reports within 10 days of month end.', 'water', 'document', '{}'::jsonb, 'Completed daily treatment operation forms for the month with transmittal proof showing submission within 10 days of month end.', 'monthly', '{"water_source": "well"}'::jsonb, '10 NYCRR 7-2.6(g), (f)(4)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.6', 'verified', 280),
  ((select id from p), 'NY-0607', 'Keep potable water accessible, label non-potable outlets, block cross-connections', 'Only potable water may be easily accessible and any non-potable supply must be conspicuously labelled. There can be no physical connection between potable and non-potable supplies, fixtures subject to back-siphonage must be protected, at least 20 psi must be held at peak demand, and common drinking utensils are prohibited.', 'water', 'inspection', '{}'::jsonb, 'A pre-season plumbing walkthrough checklist covering non-potable labelling, backflow devices, pressure and drinking fountains.', 'seasonal', '{}'::jsonb, '10 NYCRR 7-2.6(j), (k), (l), (n)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.6', 'verified', 290),
  ((select id from p), 'NY-0701', 'Keep sewage treatment and disposal working with nothing on the ground surface', 'The camp must provide and maintain sewage treatment or disposal facilities the permit-issuing official accepts. Sewage on the ground surface or anywhere children can reach it is prohibited.', 'sewage', 'inspection', '{}'::jsonb, 'Septic or treatment system service and pump-out records plus grounds inspection notes showing no surface discharge.', 'seasonal', '{}'::jsonb, '10 NYCRR 7-2.7(b)-(c)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.7', 'verified', 300),
  ((select id from p), 'NY-0702', 'Submit a sewage facility plan 30 days before building or modifying anything', 'A plan or sketch for a new or modified sewage facility must reach the permit-issuing official at least 30 days before construction, and work cannot start until that plan is approved.', 'sewage', 'document', '{}'::jsonb, 'The submitted plan or sketch with the dated approval from the permit-issuing official.', 'on_event', '{"sewage": "septic"}'::jsonb, '10 NYCRR 7-2.7(b)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.7', 'verified', 310),
  ((select id from p), 'NY-0801', 'Name a camp health director and submit the name to the permit-issuing official', 'The operator designates a camp health director to supervise health and sanitation and submits that name. At an overnight camp the health director must be on site; at a day camp availability is set out in the approved safety plan, with a designated assistant whenever the director is off site.', 'medical', 'document', '{}'::jsonb, 'The submitted health director designation plus the plan text describing on-site presence or availability and the named assistant.', 'seasonal', '{}'::jsonb, '10 NYCRR 7-2.8(a)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.8', 'verified', 320),
  ((select id from p), 'NY-0802', 'Keep the health director and designees certified in first aid and CPR', 'The camp health director and anyone acting as a designee must hold a current certificate in an accepted first aid training program and a current certificate in an accepted CPR training program.', 'medical', 'certification', '{"min_count": 1}'::jsonb, 'Non-expired first aid and CPR cards for the health director and each named designee.', 'seasonal', '{}'::jsonb, '10 NYCRR 7-2.8(a)(1)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.8', 'verified', 330),
  ((select id from p), 'NY-0803', 'Keep one first aid and one CPR certified staff member on site per 200 campers', 'Beyond the health director, the camp needs one staff member with a current first aid certificate and one with a current CPR certificate for every 200 campers, on site to respond to emergencies. Qualified aquatics staff who remain on site and available can count toward the CPR requirement.', 'medical', 'certification', '{"min_count": 1}'::jsonb, 'A staff certification roster showing the count of current first aid and CPR holders against enrolled camper numbers.', 'seasonal', '{}'::jsonb, '10 NYCRR 7-2.8(a)(2)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.8', 'verified', 340),
  ((select id from p), 'NY-0804', 'Provide an infirmary at an overnight camp or a holding area at a day camp', 'An overnight camp needs an infirmary with hot and cold running water, an examining room, isolation and convalescent space, a bathroom with flush toilets and showers, and medical supplies, unless alternative arrangements are in the safety plan. A day camp needs a holding area for ill or injured children that satisfies the permit-issuing official.', 'medical', 'inspection', '{}'::jsonb, 'A pre-season readiness checklist for the infirmary or holding area covering water, exam, isolation and supplies.', 'seasonal', '{}'::jsonb, '10 NYCRR 7-2.8(b)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.8', 'verified', 350),
  ((select id from p), 'NY-0805', 'Hold a current medical history, immunisations and emergency contact for every camper', 'Every camper needs a current confidential medical history on file including immunisation dates for diphtheria, Hib, hepatitis B, measles, mumps, polio, rubella, tetanus and varicella, updated each year. Emergency contact name, address and phone for a family member or other responsible person must be on file for every camper and every staff member.', 'medical', 'document', '{}'::jsonb, 'A camper health file per enrolled camper dated this year with the listed immunisation dates, plus an emergency contact roster covering campers and staff.', 'annual', '{}'::jsonb, '10 NYCRR 7-2.8(c)(1)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.8', 'verified', 360),
  ((select id from p), 'NY-0806', 'Give meningitis information and collect a signed response form for long-stay campers', 'An overnight camp must give parents or guardians of campers staying seven or more consecutive nights written information about meningococcal meningitis and the State-approved immunisation response form. The signed form is submitted each year and kept on file, showing either immunisation within the past ten years or an informed decision to decline.', 'medical', 'document', '{}'::jsonb, 'A signed meningococcal immunisation response form on file for each camper staying seven or more consecutive nights this year.', 'annual', '{"camp_type": "overnight"}'::jsonb, '10 NYCRR 7-2.8(c)(2)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.8', 'verified', 370),
  ((select id from p), 'NY-0807', 'Log every camper and staff injury, illness and reportable disease', 'All camper and staff injuries, illnesses and reportable diseases must be reported to the camp health director and written into the camp medical log.', 'medical', 'document', '{}'::jsonb, 'The camp medical log with dated entries for each injury, illness and reportable disease.', 'ongoing', '{}'::jsonb, '10 NYCRR 7-2.8(d)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.8', 'verified', 380),
  ((select id from p), 'NY-0808', 'Report serious injuries and abuse allegations in 24 hours and isolate contagious cases', 'Within a day the camp must notify the permit-issuing official of any death, resuscitation, hospital admission, epinephrine use, potential rabies exposure, head, neck, spine or eye injury referred for treatment, large burn, fracture, dislocation, laceration needing sutures, camper abuse allegation, or suspected water, food, air or contact spread illness. Anyone suspected of a communicable disease must be suitably isolated.', 'medical', 'document', '{}'::jsonb, 'Dated 24-hour notifications to the permit-issuing official filed alongside the matching medical log entries and isolation notes.', 'on_event', '{}'::jsonb, '10 NYCRR 7-2.8(d)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.8', 'verified', 390),
  ((select id from p), 'NY-0901', 'Provide the required toilets, handwashing and hot showers near sleeping quarters', 'Within 200 feet of sleeping quarters the camp needs one toilet or privy seat per 15 males plus one urinal per 30 males, one toilet or privy seat per 15 females, and at least one pressurised lavatory per 20 occupants. Showers run at 110 to 120 degrees with one head per 20 occupants. No privy may sit within 50 feet of a sleeping room, dining room, mess hall or kitchen.', 'facility', 'temp_log', '{}'::jsonb, 'A fixture count worksheet against peak occupancy plus shower water temperature readings inside the 110 to 120 degree band.', 'seasonal', '{"camp_type": "overnight"}'::jsonb, '10 NYCRR 7-2.9(a)-(c)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.9', 'verified', 400),
  ((select id from p), 'NY-1001', 'Carry passengers only in passenger seats, belted, within capacity, with a counselor', 'People may only ride in portions of a vehicle designed for passengers, never in a truck bed or trailer. Seat belts must be used wherever fitted, occupancy may not exceed rated capacity, and at least one counselor must be aboard any vehicle carrying children (the counselor may be the driver).', 'transportation', 'roster', '{}'::jsonb, 'Transportation manifests naming the counselor on each vehicle with camper counts against rated capacity.', 'ongoing', '{"operates_vehicles": true}'::jsonb, '10 NYCRR 7-2.10(a), (b), (e), (f)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.10', 'verified', 410),
  ((select id from p), 'NY-1002', 'Keep registration and inspection current on every camp vehicle', 'Every vehicle used to move staff or campers must carry its required registration and inspection stickers.', 'transportation', 'asset_expiry', '{}'::jsonb, 'A vehicle list with registration and inspection expiry dates, all unexpired.', 'annual', '{"operates_vehicles": true}'::jsonb, '10 NYCRR 7-2.10(c)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.10', 'verified', 420),
  ((select id from p), 'NY-1003', 'Equip every camp vehicle with the required emergency kit', 'Each vehicle used for staff or campers must carry at least a first aid kit, tools, a fire extinguisher, and flares or reflective triangles bearing a federal DOT symbol or a statement of compliance with federal motor vehicle safety standards.', 'transportation', 'inspection', '{}'::jsonb, 'A per-vehicle equipment inspection checklist confirming kit, tools, extinguisher and DOT-marked warning devices.', 'seasonal', '{"operates_vehicles": true}'::jsonb, '10 NYCRR 7-2.10(c)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.10', 'verified', 430),
  ((select id from p), 'NY-1004', 'Use drivers who are at least 18 and hold a current licence', 'The driver of any camp vehicle must be at least 18 years old and hold a current driver''s licence.', 'transportation', 'document', '{}'::jsonb, 'Copies of current driver licences for every approved camp driver, with dates of birth on file.', 'seasonal', '{"operates_vehicles": true}'::jsonb, '10 NYCRR 7-2.10(d)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.10', 'verified', 440),
  ((select id from p), 'NY-1101', 'Swim only at plan-approved, well-lit locations under the aquatics director', 'Swimming may only happen at locations the permit-issuing official approved as part of the safety plan, directly supervised by the camp aquatics director, with pools and beaches otherwise meeting Part 6. There must be enough light to supervise, and wilderness site swimming is prohibited between sunset and sunrise.', 'recreation', 'plan_section', '{}'::jsonb, 'The approved plan''s list of swim locations plus aquatics schedules showing the aquatics director present for every swim period.', 'seasonal', '{"any_of": {"has_pool": "true", "has_waterfront": "true"}}'::jsonb, '10 NYCRR 7-2.11(a)(1)-(2), (a)(3)(i)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.11', 'verified', 450),
  ((select id from p), 'NY-1102', 'Zone swimmers from non-swimmers and keep the waterfront physically safe', 'Float lines must mark at least swimmer and non-swimmer areas, non-swimmers must be conspicuously identifiable and held to water less than chest deep with narrow exceptions, and permanent areas need supervised entrances and exits, a guard station with an unobstructed view, lifesaving equipment, and pool fencing with gates locked whenever no lifeguard is on duty. Piers, floats and decking stay in good repair with required depth markings and compliant diving areas.', 'recreation', 'inspection', '{}'::jsonb, 'A waterfront inspection checklist covering float lines, non-swimmer identification, fencing and gate locks, rescue equipment, decking, depth markings and diving areas.', 'seasonal', '{"any_of": {"has_pool": "true", "has_waterfront": "true"}}'::jsonb, '10 NYCRR 7-2.11(a)(3)(ii), (iii), (v), (vi)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.11', 'verified', 460),
  ((select id from p), 'NY-1103', 'Run a buddy and board system with checks every 15 minutes and a lost swimmer plan', 'The approved plan must describe, and the camp must run, a bather accounting system identifying each bather by name, ability and assigned area, recording entry to and exit from the water, pairing buddies of equal ability, and checking all bathers against the system at least every 15 minutes. A lost swimmer plan covering clearing the water, searching and supervising the rest must be in the plan and used whenever a check fails.', 'recreation', 'pool_log', '{}'::jsonb, 'Completed buddy board sheets showing checks no more than 15 minutes apart, plus the lost swimmer procedure in the approved plan.', 'daily', '{"any_of": {"has_pool": "true", "has_waterfront": "true"}}'::jsonb, '10 NYCRR 7-2.11(a)(3)(iv)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.11', 'verified', 470),
  ((select id from p), 'NY-1104', 'Provide one lifeguard per 25 bathers and counselors at 1:10, 1:8 or 1:6 in the water', 'There must be one qualified lifeguard per 25 bathers, with no guard covering more than 3,400 square feet of pool or 50 yards of shoreline, and patrol boats or offshore stations where swimming goes beyond 150 feet from shore. Counselors supervising campers in the water run at one to ten, one to eight under age eight and one to six under age six, stationed at poolside, on the beach or in the water.', 'recreation', 'roster', '{}'::jsonb, 'Swim period logs recording bather counts against guards on stand and counselor assignments by age band.', 'ongoing', '{"any_of": {"has_pool": "true", "has_waterfront": "true"}}'::jsonb, '10 NYCRR 7-2.11(a)(3)(vii)-(viii)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.11', 'verified', 480),
  ((select id from p), 'NY-1105', 'Get permission slips and use permitted, pre-arranged venues with correct trip staffing', 'Trip swimming needs a signed parent or guardian permission statement per camper, and may only use New York pools or beaches with a valid health department permit or run by a State agency (never a residential pool), pre-arranged for bather load and staffing. The camp supplies one qualified lifeguard or specially trained staff member per 75 campers where the venue provides its own guards, or one guard per 25 bathers where it does not, with counselors at 1:8 or 1:6 and the buddy and board system in use.', 'recreation', 'document', '{}'::jsonb, 'Signed swim permission forms for the trip roster, the venue''s operating permit and written pre-arrangement, and the trip aquatic staffing sheet.', 'on_event', '{"offers_trips": true}'::jsonb, '10 NYCRR 7-2.11(a)(4)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.11', 'verified', 490),
  ((select id from p), 'NY-1106', 'Meet the wilderness swimming and incidental immersion rules before campers enter water', 'Wilderness swimming needs a marked area no deeper than five feet with adequate clarity, gentle bottom, currents under three feet per second, within 50 yards of shoreline and 75 feet from shore, staffed by one lifeguard aged 18 or over per 25 bathers with two CPR-certified staff, counselors at 1:8 or 1:6, a rescue tube or buoy and pocket mask per guard, and no head-first diving or jumping from cliffs, trees or rope swings. Incidental immersion deeper than mid-calf needs approved plan procedures and staff must test the whole area first.', 'recreation', 'inspection', '{}'::jsonb, 'A site assessment recording depth, clarity, slope and current, with the staffing roster, rescue equipment checklist and the pre-entry water test record.', 'on_event', '{"has_waterfront": true}'::jsonb, '10 NYCRR 7-2.11(a)(5), (j)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.11', 'verified', 500),
  ((select id from p), 'NY-1107', 'Set up and supervise the rifle range and lock guns and ammunition separately', 'The range needs a bullet-containing backstop with keep out signs and a red flag when in use, plus a firing line and ready line. The instructor stays on the range with an assistant at no more than ten campers per staff member on the firing line, campers get safety instruction before firing, the minimum age follows the Penal Law and the plan, and the instructor keeps rifles clean and in repair with a check-out system, storing guns and ammunition separately in locked cabinets.', 'recreation', 'inspection', '{}'::jsonb, 'Range inspection notes, firing line staffing logs, camper safety instruction records and the firearm and ammunition check-out log.', 'seasonal', '{"has_riflery": true}'::jsonb, '10 NYCRR 7-2.11(b)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.11', 'verified', 510),
  ((select id from p), 'NY-1108', 'Set up the archery range, lock the equipment and hold a 1:10 firing line ratio', 'The archery range must be clear of other program areas and marked to warn passers-by, with at least 50 yards of clearance or a net behind each target, a common firing line and a marked ready line. Bows and arrows stay in a locked cabinet, and one archery staff member covers no more than ten campers on the firing line.', 'recreation', 'inspection', '{}'::jsonb, 'A range layout inspection record, the locked storage check and firing line staffing sheets.', 'seasonal', '{"has_archery": true}'::jsonb, '10 NYCRR 7-2.11(c)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.11', 'verified', 520),
  ((select id from p), 'NY-1109', 'Assess riders, staff trail rides at 1:10 and require certified helmets', 'A competent riding instructor must judge each camper''s experience and skill before assigning a horse and deciding on ring or trail riding. Trail excursions need one experienced instructor per ten riders and at least two staff. Headgear permanently labelled to ASTM F1163 must be worn at all times and riders need heeled shoes or closed stirrups.', 'recreation', 'inspection', '{}'::jsonb, 'Rider skill assessment records, trail ride staffing sheets and a helmet inventory showing ASTM F1163 labels.', 'per_session', '{"has_equestrian": true}'::jsonb, '10 NYCRR 7-2.11(d)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.11', 'verified', 530),
  ((select id from p), 'NY-1110', 'Inspect program equipment for defects at frequent intervals', 'All camp equipment must be free of hazards, anchored where needed, installed and used according to the manufacturer''s instructions, and inspected by the operator at frequent intervals for defects. Personal weapons or bows brought to camp need the operator''s permission and stay in a locked cabinet.', 'recreation', 'inspection', '{}'::jsonb, 'A dated equipment inspection log covering each activity area, with defects and repairs recorded.', 'ongoing', '{}'::jsonb, '10 NYCRR 7-2.11(f)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.11', 'needs_verification', 540),
  ((select id from p), 'NY-1111', 'Put an activity leader on every on-site activity and hold 1:8 for specialised ones', 'Each activity on camp property needs an activity leader, and activities held where extra camp staff are not readily available need an activity leader plus one more staff member. Wilderness, equestrian, boating and similar specialised activities run at one counselor per eight campers, or one per six for campers under six.', 'recreation', 'roster', '{}'::jsonb, 'The daily activity schedule showing the assigned leader and staff to camper counts for each specialised activity.', 'ongoing', '{}'::jsonb, '10 NYCRR 7-2.11(g)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.11', 'verified', 550),
  ((select id from p), 'NY-1112', 'Register and inspect boats, life-jacket every occupant, plan the specialty activities', 'Motorised boats must be registered with the DMV with the number on the bow and current registration and inspection certificates available for the inspector. Every boat occupant wears a Coast Guard approved life jacket, and a lifeguard rides in any craft rated for eight or more carrying non-swimmers. Practices and equipment for specialty waterfront activities and the conditions for non-motorised boats must be in the approved plan, with each specialty led by a counselor trained in it.', 'recreation', 'asset_expiry', '{}'::jsonb, 'Current boat registration and inspection certificates, a life jacket inventory sized to boat capacity, and the specialty waterfront section of the plan with trainer records.', 'annual', '{"has_waterfront": true}'::jsonb, '10 NYCRR 7-2.11(h)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.11', 'verified', 560),
  ((select id from p), 'NY-1113', 'Send a trip leader plus a counselor on every trip and review the plan beforehand', 'Every camp trip needs a trip leader and at least one counselor, at one counselor per eight campers for swimming, wilderness, equestrian, boating and similar trips (one per six under age six) and one per twelve when transporting to an activity site. Staff supervising a trip must review the camp safety plan for that trip within the 24 hours before departure unless they ran an identical trip or took pre-camp training in the previous week.', 'recreation', 'roster', '{}'::jsonb, 'A trip roster naming the trip leader and counselors against camper counts, with signed pre-trip plan review sheets dated within 24 hours of departure.', 'on_event', '{"offers_trips": true}'::jsonb, '10 NYCRR 7-2.11(i)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.11', 'verified', 570),
  ((select id from p), 'NY-1601', 'Issue clean bedding, change linens weekly and keep bunks safe and spaced', 'Beds, mattresses and sleeping accessories the camp supplies must be clean and in good condition at issue, with clean sheets and pillowcases provided weekly and laundry facilities available when people bring their own linens. Bunks must be structurally sound with guardrails on upper beds, 27 inches of clear space above the sleeping surface, six feet between sleepers'' heads, no triple deckers, and clear aisles to exits.', 'facility', 'inspection', '{}'::jsonb, 'Weekly linen change records plus a cabin inspection checklist covering guardrails, spacing and aisle clearance.', 'weekly', '{"camp_type": "overnight"}'::jsonb, '10 NYCRR 7-2.16(a)-(b)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.16', 'verified', 580),
  ((select id from p), 'NY-1801', 'Install and maintain fire alarm and detection systems where size or height requires', 'A building used for sleeping by 50 or more people, or any sleeping building two or more stories tall, needs a fire alarm audible throughout the camp. Sleeping buildings three or more stories tall also need automatic fire detection with smoke detectors in corridors, assembly areas, storage rooms and stairways plus heat detection in kitchens.', 'fire', 'inspection', '{}'::jsonb, 'Alarm and detection system test and maintenance reports for each qualifying building.', 'annual', '{"camp_type": "overnight"}'::jsonb, '10 NYCRR 7-2.18(b)(1)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.18', 'verified', 590),
  ((select id from p), 'NY-1802', 'Put a smoke alarm in every sleeping unit, with visual alarms where campers need them', 'At least one single station smoke detecting alarm goes on or near the ceiling of each sleeping unit; battery devices are acceptable. Sleeping quarters occupied by visually or audibly impaired campers need portable audible and visual detectors, or those detectors hard wired into a central alarm system. Tents and lean-tos are exempt.', 'fire', 'inspection', '{}'::jsonb, 'A per-cabin smoke alarm inventory with pre-season test dates, plus a record matching campers with sensory impairments to cabins fitted with audible and visual detectors.', 'seasonal', '{"camp_type": "overnight"}'::jsonb, '10 NYCRR 7-2.18(b)(2)-(3)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.18', 'verified', 600),
  ((select id from p), 'NY-1803', 'Run a fire drill in the first 48 hours of every session and keep a verified log', 'A fire drill must be held within the first 48 hours of each camping session and periodically thereafter as the safety plan sets out. The log of drill dates and times must be kept, verified by the camp director, and available for inspection at all times.', 'fire', 'drill', '{"min_count": 1}'::jsonb, 'The fire drill log with dates and times for each session, signed off by the camp director.', 'per_session', '{}'::jsonb, '10 NYCRR 7-2.18(b)(4)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.18', 'verified', 610),
  ((select id from p), 'NY-1804', 'Inspect fire protection equipment regularly and tag extinguishers before the season', 'The operator is responsible for regular inspection of every fire protection facility and piece of equipment. Fire extinguishers and other firefighting equipment must be provided, inspected and tagged by the operator before the camp season and kept operable at all times.', 'fire', 'asset_expiry', '{}'::jsonb, 'An extinguisher inventory with current inspection tag dates plus the dated fire equipment and system inspection log.', 'annual', '{}'::jsonb, '10 NYCRR 7-2.18(b)(5), (e)(3)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.18', 'needs_verification', 620),
  ((select id from p), 'NY-1805', 'Keep exits unobstructed with the required egress routes, signage and lighting', 'Means of egress must stay unobstructed and easy to travel at all times and be protected from hazardous areas. Sleeping quarters holding 15 or more people and every floor of a multi-story building need two separated exits, doors must swing in the direction of egress and not lock against it, and rooms holding 15 or more or with exits not readily visible need lighted exit signs, with emergency lighting where required.', 'fire', 'inspection', '{}'::jsonb, 'A building-by-building egress inspection checklist covering exit counts, door swing and hardware, signage and emergency lighting.', 'seasonal', '{}'::jsonb, '10 NYCRR 7-2.18(c)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.18', 'verified', 630),
  ((select id from p), 'NY-1806', 'Store flammables in a separate locked building and control heating hazards', 'Gasoline, kerosene and other flammable materials must be labelled and stored in a separate locked, unoccupied building, and oil-base paints and thinners in approved paint lockers or a separate building. Tents must be flame retardant, stoves and heat sources installed and maintained per the manufacturer''s instructions, no unvented fossil fuel heaters, and no water heaters in sleeping quarters.', 'fire', 'inspection', '{}'::jsonb, 'A pre-season inspection record for the flammable storage building, tent flame retardancy documentation and heater installation checks.', 'seasonal', '{}'::jsonb, '10 NYCRR 7-2.18(d), (e)(1)-(2)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.18', 'verified', 640),
  ((select id from p), 'NY-1901', 'Run the kitchen under the Part 14 food service rules and feed campers adequately', 'Kitchens, dining areas and food service at a children''s camp are held to the State''s food service establishment standards in Part 14, covering food temperatures, handling, equipment and sanitation. Food the camp provides must be sufficient in quantity and quality for each child''s nutritional needs.', 'food', 'temp_log', '{}'::jsonb, 'Part 14 food service records for the season including cooking, holding and cooler temperature logs, the latest inspection report, and posted menus.', 'ongoing', '{"has_kitchen": true}'::jsonb, '10 NYCRR 7-2.19(a)-(b)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.19', 'needs_verification', 650),
  ((select id from p), 'NY-2001', 'Store pesticides and toxic chemicals in original containers in designated areas', 'Agricultural, commercial and household pesticides and toxic chemicals must be stored and used so they cause no air, surface water or groundwater pollution and no hazard to camp occupants, kept in their original containers in areas designated for that use.', 'facility', 'inspection', '{}'::jsonb, 'A chemical storage inventory and inspection record showing original labelled containers in the designated locations.', 'seasonal', '{}'::jsonb, '10 NYCRR 7-2.20', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.20', 'verified', 660),
  ((select id from p), 'NY-2101', 'Keep grounds free of vermin, bats, noxious weeds and uncontrolled refuse', 'The property must be free of insect and rodent infestations that could be a nuisance or health hazard, with bats excluded from living areas. Ragweed, poison ivy, oak and sumac and other noxious weeds must be controlled, and refuse storage, handling and disposal facilities maintained so they cause no nuisance, infestation or pollution.', 'facility', 'inspection', '{}'::jsonb, 'Pest control service records, bat exclusion notes, grounds maintenance records for noxious weeds, and refuse collection or disposal records.', 'seasonal', '{}'::jsonb, '10 NYCRR 7-2.21, 7-2.22, 7-2.23(b)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.21', 'verified', 670),
  ((select id from p), 'NY-2501', 'Staff at 1:2 for campers who cannot manage their own mobility equipment', 'Campers who use a wheelchair, adaptive equipment or bracing to move around but cannot fit, secure or operate those devices themselves must be supervised at one counselor for every two campers.', 'supervision', 'roster', '{}'::jsonb, 'Group assignment sheets identifying campers in this category and the counselors assigned to them.', 'ongoing', '{"enrolls_campers_with_disabilities": true}'::jsonb, '10 NYCRR 7-2.25(a)(1)(i)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.25', 'verified', 680),
  ((select id from p), 'NY-2502', 'Obtain each camper''s care plan and train direct-care staff on their specific needs', 'The operator must get any existing individual treatment, care and behavioural plans for a camper with a disability, and staff must run procedures adequate to protect that camper based on the plan, consulting the parent, guardian or clinical team when needed. Staff providing direct care must be trained on the specific needs of the campers in their charge.', 'medical', 'document', '{}'::jsonb, 'The received individual plan on file for each such camper plus signed training records naming the campers and needs covered for each direct-care staff member.', 'per_session', '{"enrolls_campers_with_disabilities": true}'::jsonb, '10 NYCRR 7-2.25(a)(1)(ii), (a)(2)(i)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.25', 'verified', 690),
  ((select id from p), 'NY-2503', 'Expand the medical history for campers with disabilities', 'On top of the standard confidential medical history, the file for a camper with a disability must record restrictions, allergies, medications, special dietary needs and other pre-existing medical, physical or psychological conditions, plus the camper''s physician''s name, address and telephone number.', 'medical', 'document', '{}'::jsonb, 'Completed expanded health history forms carrying restrictions, medications, diet and physician contact for each such camper.', 'annual', '{"enrolls_campers_with_disabilities": true}'::jsonb, '10 NYCRR 7-2.25(a)(2)(ii)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.25', 'verified', 700),
  ((select id from p), 'NY-2504', 'Identify modified diets before arrival and have the health director review them', 'Modified diets and other special needs tied to a camper''s disability must be identified before the camper arrives, planned for, provided according to the directions supplied, and reviewed by the designated camp health director.', 'food', 'document', '{}'::jsonb, 'A pre-arrival dietary and special needs list signed off by the camp health director and given to the kitchen.', 'per_session', '{"enrolls_campers_with_disabilities": true}'::jsonb, '10 NYCRR 7-2.25(a)(2)(iii)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.25', 'verified', 710),
  ((select id from p), 'NY-2505', 'Use 1:1 and 1:5 aquatic ratios and get written swim permission', 'In the water, each camper who is non-ambulatory or whose disability raises the risk of an in-water emergency such as uncontrolled epilepsy gets one counselor to themselves; other campers with a developmental disability are supervised at one staff member per five. No camper with a developmental disability may swim without a written permission statement signed by the parent, guardian or residential care provider on file.', 'supervision', 'roster', '{}'::jsonb, 'Swim period staffing sheets showing the one-to-one and one-to-five assignments by camper name, with signed swim permission statements on file.', 'ongoing', '{"enrolls_campers_with_disabilities": true}'::jsonb, '10 NYCRR 7-2.25(a)(3)(i)-(iii)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.25', 'verified', 720),
  ((select id from p), 'NY-2506', 'Train aquatic staff on the seizure procedure and refresh it every two weeks', 'The approved safety plan must contain a procedure for handling seizures and aspiration of water for campers with developmental disabilities. All pool and beach staff must be trained on it before the camp opens, and in-service training on the procedure must be run and documented every two weeks during operation unless the plan sets a different approved schedule.', 'training', 'training', '{}'::jsonb, 'The plan procedure plus pre-season and every-two-weeks in-service sign-in sheets for all pool and beach staff.', 'ongoing', '{"enrolls_campers_with_disabilities": true}'::jsonb, '10 NYCRR 7-2.25(a)(3)(iv)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.25', 'verified', 730),
  ((select id from p), 'NY-2507', 'Adapt bathrooms, sleeping quarters and paths for campers with physical disabilities', 'Lavatories and showers used by a camper with a physical disability need specialised fixtures, grab bars or appropriate controls, and water must not exceed 110 degrees for campers who cannot safely moderate temperature. Buildings housing non-ambulatory or wheelchair-using campers need code-compliant ramps, those campers may not sleep above the ground floor, and exterior paths must be clear with a surface suitable in bad weather.', 'facility', 'inspection', '{}'::jsonb, 'An accessibility inspection record covering fixtures, a 110 degree water temperature reading, ramps, sleeping assignments and path condition.', 'seasonal', '{"enrolls_campers_with_disabilities": true}'::jsonb, '10 NYCRR 7-2.25(a)(4)-(6)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.25', 'verified', 740),
  ((select id from p), 'NY-2508', 'Screen staff against the Justice Center list and train them as mandated reporters', 'At a camp for children with developmental disabilities, before hiring anyone who may have direct contact with campers the operator must verify they are not on the Justice Center staff exclusion list and then consult the State Central Registry of Child Abuse and Maltreatment. Staff must be trained on mandated reporting, the Justice Center hotline number posted where reporters and campers can see it, and the Justice Center code of conduct issued at hire and annually with signed acknowledgement.', 'personnel', 'screening', '{}'::jsonb, 'Dated exclusion list and State Central Registry results for each hire, mandated reporter training sign-ins, a photo of the posted hotline number, and signed code of conduct acknowledgements.', 'annual', '{"enrolls_campers_with_disabilities": true}'::jsonb, '10 NYCRR 7-2.25(b)(6)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.25', 'needs_verification', 750),
  ((select id from p), 'NY-2509', 'Report incidents immediately, notify on the clock, and close out corrective actions', 'At a camp for children with developmental disabilities, staff must immediately report abuse, neglect or significant incidents to the permit-issuing official and the Justice Center''s vulnerable persons central register, take documented protective action, notify alleged victims within 24 hours and potential witnesses within 48. Corrective action plans go to the permit-issuing official within 45 days of an investigation closing and are implemented within 90 days, and the camp keeps an incident review committee that meets in any year with a reportable incident.', 'records', 'document', '{}'::jsonb, 'The incident file with the immediate report, protective actions, dated victim and witness notifications, corrective action plans with dates, and incident review committee minutes.', 'on_event', '{"enrolls_campers_with_disabilities": true}'::jsonb, '10 NYCRR 7-2.25(b)(4)-(5), (b)(8)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.25', 'needs_verification', 760),
  ((select id from p), 'NY-2510', 'Meet the extra director, clinician and vehicle staffing rules for these camps', 'A camp for children with developmental disabilities needs a health director who is a physician, physician''s assistant, registered nurse or licensed practical nurse on site the whole season, and a camp director with a human services degree plus specialised training or a year of relevant experience, not on the Justice Center exclusion list, who writes a staff training program suited to the campers enrolled. Vehicles carrying these campers need a counselor in addition to the driver unless the approved plan says otherwise.', 'personnel', 'certification', '{"min_count": 1}'::jsonb, 'The health director''s professional licence and duty schedule, the camp director''s degree and specialised training records, the written staff training program, and vehicle staffing manifests.', 'seasonal', '{"enrolls_campers_with_disabilities": true}'::jsonb, '10 NYCRR 7-2.25(b)(2)-(3)', 'https://www.law.cornell.edu/regulations/new-york/10-NYCRR-7-2.25', 'needs_verification', 770)
on conflict (profile_id, req_code) do update
  set label = excluded.label, summary = excluded.summary, category = excluded.category,
      evidence_type = excluded.evidence_type, evidence_rule = excluded.evidence_rule,
      evidence_hint = excluded.evidence_hint, frequency = excluded.frequency,
      applies_when = excluded.applies_when, citation = excluded.citation,
      citation_url = excluded.citation_url, verify_status = excluded.verify_status,
      sort_order = excluded.sort_order;
